const T = 12.0;
const swing = (s, lo, hi) => (s >= 0 ? s * hi : -s * lo);
export const clips = {
  range: {
    label: "Arm, then head, through their range",
    duration: T,
    update(t, m) {
      const half = T / 2;
      const tilt = t < half ? swing(Math.sin(2 * Math.PI * t / half), -45.0, 135.0) : 0;
      const head = t < half ? 0 : swing(Math.sin(2 * Math.PI * (t - half) / half), -45.0, 175.0);
      for (const label of ['head', 'led_module', 'm3x8_screw:left', 'm3x8_screw:right']) {
        m.get(label).rotate([0, -1, 0], head, [84.71528727020922, 0.0, 211.83040885779835]).rotate([0, -1, 0], tilt, [-30.0, 0.0, 48.0]);
      }
      for (const label of ['arm', 'm5x30_screw:head_hinge', 'm5_locknut:head_hinge']) {
        m.get(label).rotate([0, -1, 0], tilt, [-30.0, 0.0, 48.0]);
      }
    },
  },
};
